window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e304b9cb029a2e67"]={"versions": [{"id": "FIG-e304b9cb029a2e67", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem AUTOSAR-ECU-Resource-Template (<code>AUTOSAR_ResourceTemplateECU</code>). Das Diagramm modelliert die Hardware-Ressourcenbeschreibung für Taktquellen und Oszillatoren innerhalb des Modulpakets <code>ECUElectronics</code> sowie deren Anbindung an Hardware-Interrupt-Schnittstellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm spezifiziert vier Klassen und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong><code>Oscillator</code></strong> (Paket <code>ECUElectronics</code>): Repräsentiert die Oszillator-Hardware.</li>\n<li>Attribute:</li>\n<li><code>adjustible: Boolean [0..1]</code></li>\n<li><code>oscillatorStartupTime: Float [0..1]</code></li>\n<li><code>oscillatorTolerance: Float [0..1]</code></li>\n<li><code>oscillatorJitter: Float [0..1]</code></li>\n<li><code>oscillatorMode: Enumeration{fundamental, overtone} [0..1]</code></li>\n<li>Assoziationen:</li>\n<li>Komposition auf sich selbst mit Rollenbezeichnung <code>+backupOscillator</code> und Multiplizität <code>0..1</code> (optionaler Backup-Oszillator).</li>\n<li>Komposition auf <code>FrequencyRange</code> mit Rollenbezeichnung <code>+oscillatorFrequencyRange</code> und Multiplizität <code>1</code>.</li>\n<li>Abhängigkeitsbeziehung (gestrichelter Pfeil) mit Stereotyp/Label <code>failure notification</code> zu <code>InterruptProduceHWPort</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>Clock</code></strong> (Paket <code>ECUElectronics</code>): Repräsentiert einen Taktgenerator bzw. Taktbaum-Element.</li>\n<li>Attribute:</li>\n<li><code>type: Enumeration{PLL, divider}</code></li>\n<li><code>adjustable: Boolean [0..1]</code></li>\n<li><code>clockStartupTime: Float</code></li>\n<li><code>clockTolerance: Float</code></li>\n<li><code>clockJitter: Float</code></li>\n<li>Assoziationen:</li>\n<li>Gerichtete Assoziation zu <code>Oscillator</code> mit Rollenbezeichnung <code>+oscillator</code> und Multiplizität <code>1..*</code>.</li>\n<li>Komposition auf <code>FrequencyRange</code> mit Rollenbezeichnung <code>+frequency</code> und Multiplizität <code>1</code>.</li>\n<li>Abhängigkeitsbeziehung (gestrichelter Pfeil) mit Stereotyp/Label <code>failure notification</code> zu <code>InterruptProduceHWPort</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>FrequencyRange</code></strong>: Beschreibt zulässige bzw. typische Frequenzen.</li>\n<li>Attribute:</li>\n<li><code>minFrequency: Float</code></li>\n<li><code>maxFrequency: Float</code></li>\n<li><code>typicalFrequency: Float [0..1]</code></li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>InterruptProduceHWPort</code></strong> (Paket bzw. Kontext <code>InterruptHWPort</code>): Repräsentiert einen Hardware-Port zur Erzeugung von Interrupts bei Fehlern (<code>failure notification</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt strukturelle Abhängigkeiten: Taktgeneratoren (<code>Clock</code>) referenzieren mindestens einen zugrundeliegenden Oszillator (<code>1..*</code>), während Oszillatoren optional über einen redundanten Ausfalloszillator (<code>+backupOscillator [0..1]</code>) verfügen können. Bei Oszillator- oder Taktfehlern können über gerichtete Abhängigkeiten Benachrichtigungssignale an Hardware-Interrupt-Ports (<code>InterruptProduceHWPort</code>) ausgelöst werden (<code>failure notification</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Metamodell dient der formalen Spezifikation von Hardware-Eigenschaften im ECU-Resource-Template:</p>\n<ul class=\"fig-list\">\n<li>Beachtung der Multiplizitäten: Jede <code>Clock</code> benötigt zwingend mindestens einen zugeordneten <code>Oscillator</code> (<code>1..*</code>) sowie genau einen Frequenzbereich (<code>+frequency [1]</code>).</li>\n<li><code>Oscillator</code> besitzt zwingend genau einen <code>oscillatorFrequencyRange [1]</code>.</li>\n<li>Optionale Attribute (<code>[0..1]</code>) ermöglichen flexible Modellierung unvollständiger Datenblattangaben.</li>\n<li>Rechtschreibhinweis: Das Attribut in <code>Oscillator</code> ist als <code>adjustible</code> spezifiziert, während in <code>Clock</code> die Schreibweise <code>adjustable</code> lautet.</li>\n<li>Die Fehlerbenachrichtigung (<code>failure notification</code>) erfordert bei Ausfallerkennung eine Zuordnung zu einem Interrupt-Erzeugungsport (<code>InterruptProduceHWPort</code>).</li>\n</ul>"}, {"id": "FIG-fb8cf5f591fd51b8", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus dem AUTOSAR-ECU-Resource-Template (<code>AUTOSAR_ResourceTemplateECU</code>). Das Diagramm modelliert die Hardware-Ressourcenbeschreibung für Taktquellen und Oszillatoren innerhalb des Modulpakets <code>ECUElectronics</code> sowie deren Anbindung an Hardware-Interrupt-Schnittstellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm spezifiziert vier Klassen und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong><code>Oscillator</code></strong> (Paket <code>ECUElectronics</code>): Repräsentiert die Oszillator-Hardware.</li>\n<li>Attribute:</li>\n<li><code>adjustible: Boolean [0..1]</code></li>\n<li><code>oscillatorStartupTime: Float [0..1]</code></li>\n<li><code>oscillatorTolerance: Float [0..1]</code></li>\n<li><code>oscillatorJitter: Float [0..1]</code></li>\n<li><code>oscillatorMode: Enumeration{fundamental, overtone} [0..1]</code></li>\n<li>Assoziationen:</li>\n<li>Komposition auf sich selbst mit Rollenbezeichnung <code>+backupOscillator</code> und Multiplizität <code>0..1</code> (optionaler Backup-Oszillator).</li>\n<li>Komposition auf <code>FrequencyRange</code> mit Rollenbezeichnung <code>+oscillatorFrequencyRange</code> und Multiplizität <code>1</code>.</li>\n<li>Abhängigkeitsbeziehung (gestrichelter Pfeil) mit Stereotyp/Label <code>failure notification</code> zu <code>InterruptProduceHWPort</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>Clock</code></strong> (Paket <code>ECUElectronics</code>): Repräsentiert einen Taktgenerator bzw. Taktbaum-Element.</li>\n<li>Attribute:</li>\n<li><code>type: Enumeration{PLL, divider}</code></li>\n<li><code>adjustable: Boolean [0..1]</code></li>\n<li><code>clockStartupTime: Float</code></li>\n<li><code>clockTolerance: Float</code></li>\n<li><code>clockJitter: Float</code></li>\n<li>Assoziationen:</li>\n<li>Gerichtete Assoziation zu <code>Oscillator</code> mit Rollenbezeichnung <code>+oscillator</code> und Multiplizität <code>1..*</code>.</li>\n<li>Komposition auf <code>FrequencyRange</code> mit Rollenbezeichnung <code>+frequency</code> und Multiplizität <code>1</code>.</li>\n<li>Abhängigkeitsbeziehung (gestrichelter Pfeil) mit Stereotyp/Label <code>failure notification</code> zu <code>InterruptProduceHWPort</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>FrequencyRange</code></strong>: Beschreibt zulässige bzw. typische Frequenzen.</li>\n<li>Attribute:</li>\n<li><code>minFrequency: Float</code></li>\n<li><code>maxFrequency: Float</code></li>\n<li><code>typicalFrequency: Float [0..1]</code></li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>InterruptProduceHWPort</code></strong> (Paket bzw. Kontext <code>InterruptHWPort</code>): Repräsentiert einen Hardware-Port zur Erzeugung von Interrupts bei Fehlern (<code>failure notification</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt strukturelle Abhängigkeiten: Taktgeneratoren (<code>Clock</code>) referenzieren mindestens einen zugrundeliegenden Oszillator (<code>1..*</code>), während Oszillatoren optional über einen redundanten Ausfalloszillator (<code>+backupOscillator [0..1]</code>) verfügen können. Bei Oszillator- oder Taktfehlern können über gerichtete Abhängigkeiten Benachrichtigungssignale an Hardware-Interrupt-Ports (<code>InterruptProduceHWPort</code>) ausgelöst werden (<code>failure notification</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Metamodell dient der formalen Spezifikation von Hardware-Eigenschaften im ECU-Resource-Template:</p>\n<ul class=\"fig-list\">\n<li>Beachtung der Multiplizitäten: Jede <code>Clock</code> benötigt zwingend mindestens einen zugeordneten <code>Oscillator</code> (<code>1..*</code>) sowie genau einen Frequenzbereich (<code>+frequency [1]</code>).</li>\n<li><code>Oscillator</code> besitzt zwingend genau einen <code>oscillatorFrequencyRange [1]</code>.</li>\n<li>Optionale Attribute (<code>[0..1]</code>) ermöglichen flexible Modellierung unvollständiger Datenblattangaben.</li>\n<li>Rechtschreibhinweis: Das Attribut in <code>Oscillator</code> ist als <code>adjustible</code> spezifiziert, während in <code>Clock</code> die Schreibweise <code>adjustable</code> lautet.</li>\n<li>Die Fehlerbenachrichtigung (<code>failure notification</code>) erfordert bei Ausfallerkennung eine Zuordnung zu einem Interrupt-Erzeugungsport (<code>InterruptProduceHWPort</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-e304b9cb029a2e67", "to": "FIG-fb8cf5f591fd51b8", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
